(function () {
  "use strict";

  function findClosing(text, delimiter, start) {
    var index = start;
    while (index < text.length) {
      var found = text.indexOf(delimiter, index);
      if (found < 0) return -1;
      if (found === 0 || text.charAt(found - 1) !== "\\") return found;
      index = found + delimiter.length;
    }
    return -1;
  }

  function renderTextNode(node, options) {
    var text = node.nodeValue;
    var delimiters = (options && options.delimiters) || [];
    var parent = node.parentNode;
    var fragment = document.createDocumentFragment();
    var index = 0;
    var changed = false;

    while (index < text.length) {
      var best = null;
      delimiters.forEach(function (delimiter) {
        var start = text.indexOf(delimiter.left, index);
        if (start >= 0 && (!best || start < best.start)) {
          best = { delimiter: delimiter, start: start };
        }
      });

      if (!best) break;
      var expressionStart = best.start + best.delimiter.left.length;
      var end = findClosing(text, best.delimiter.right, expressionStart);
      if (end < 0) break;

      if (best.start > index) {
        fragment.appendChild(document.createTextNode(text.slice(index, best.start)));
      }

      var expression = text.slice(expressionStart, end);
      var wrapper = document.createElement(best.delimiter.display ? "div" : "span");
      wrapper.className = best.delimiter.display ? "katex-display" : "katex-inline";
      wrapper.innerHTML = window.katex.renderToString(expression, {
        throwOnError: options && options.throwOnError
      });
      fragment.appendChild(wrapper);
      index = end + best.delimiter.right.length;
      changed = true;
    }

    if (!changed) return;
    if (index < text.length) {
      fragment.appendChild(document.createTextNode(text.slice(index)));
    }
    parent.replaceChild(fragment, node);
  }

  function walk(node, options) {
    if (!node) return;
    if (node.nodeType === Node.TEXT_NODE) {
      renderTextNode(node, options || {});
      return;
    }
    if (node.nodeType !== Node.ELEMENT_NODE) return;
    var tag = node.tagName.toLowerCase();
    if (tag === "script" || tag === "style" || tag === "code" || tag === "pre") return;
    Array.prototype.slice.call(node.childNodes).forEach(function (child) {
      walk(child, options);
    });
  }

  window.renderMathInElement = function (element, options) {
    try {
      walk(element, options || {});
    } catch (error) {
      if (options && options.throwOnError) throw error;
      if (window.console) console.warn("KaTeX auto-render fallback error:", error);
    }
  };
}());
